import express, { Express } from 'express';
import { OrderController } from './controllers/OrderController';
import { StockController } from './controllers/StockController';
import { errorHandler } from './middleware/errorHandler';
import { notFoundHandler } from './middleware/notFoundHandler';

export interface Controllers {
  readonly orders: OrderController;
  readonly stock: StockController;
}

export function createApp({ orders, stock }: Controllers): Express {
  const app = express();
  app.use(express.json());

  app.get('/health', (_req, res) => {
    res.json({ status: 'ok' });
  });

  app.get('/stock', stock.list);
  app.get('/stock/:id', stock.get);

  app.post('/orders', orders.place);
  app.get('/orders', orders.list);
  app.get('/orders/:id', orders.get);
  app.post('/orders/:id/pay', orders.pay);
  app.post('/orders/:id/pack', orders.pack);
  app.post('/orders/:id/ship', orders.ship);
  app.post('/orders/:id/deliver', orders.deliver);
  app.post('/orders/:id/cancel', orders.cancel);

  app.use(notFoundHandler);
  app.use(errorHandler);
  return app;
}

